export function distance(a,b){const r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlon=(b.lon-a.lon)*r;return 6371*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2)));}
export function orderedPoints(start,stops,end){if(!start||!end)throw Error('Choose a starting location and destination from the suggestions.');if(stops.some(s=>s.text.trim()&&!s.place))throw Error('Choose each stop from the suggestions, or clear it.');return [start,...stops.filter(s=>s.place).map(s=>s.place),end];}
export function parseRoute(data){const f=data.features?.find(f=>f.geometry?.type==='LineString');if(!f||f.geometry.coordinates.length<2)throw Error('No cycling route found. Try a nearby road or park entrance.');const p=f.properties,rows=p.messages||[],header=rows[0]||[],di=header.indexOf('Distance'),ti=header.indexOf('WayTags');let total=0,cycle=0;for(const row of rows.slice(1)){const d=Number(row[di]);if(!Number.isFinite(d)||d<0)continue;total+=d;const tags=String(row[ti]);if(/\bhighway=cycleway\b/.test(tags)||(/\bhighway=(path|footway)\b/.test(tags)&&/\bbicycle=(designated|yes|permissive)\b/.test(tags)))cycle+=d;}return {coordinates:f.geometry.coordinates,metres:Number(p['track-length']),seconds:Number(p['total-time']),ascent:Number(p['filtered ascend']),coverage:total?cycle/total*100:null};}
export function chooseRoutes(candidates){if(!candidates.length)throw Error('Routing is unavailable. Please try again.');return {best:[...candidates].sort((a,b)=>(b.coverage??-1)-(a.coverage??-1)||a.seconds-b.seconds)[0],fastest:[...candidates].sort((a,b)=>a.seconds-b.seconds)[0]};}
export function xml(s){return String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));}
export function gpx(route,points,name){return `<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="CycleRoute" xmlns="http://www.topografix.com/GPX/1/1"><metadata><name>${xml(name)}</name></metadata>${points.map(p=>`<wpt lat="${p.lat}" lon="${p.lon}"><name>${xml(p.name)}</name></wpt>`).join('')}<trk><name>${xml(name)}</name><trkseg>${route.coordinates.map(c=>`<trkpt lat="${c[1]}" lon="${c[0]}">${Number.isFinite(c[2])?`<ele>${c[2]}</ele>`:''}</trkpt>`).join('')}</trkseg></trk></gpx>`;}
